float matan (float x)
{return x*(1.061 - abs(x)*0.274);}

float matan2 (float im, float re) //Version ohne Pruefing auf (0,0);
{float x;
   if (abs(re) > abs(im)) 
   {x = matan (im/re); 
    if (re<0) {x += M_PI;}
   }
   else
   {x = M_PI/2 -matan (re/im); 
   if (im<0) {x += M_PI;}
   } 
//  return (x>=M_PI? x-2*M_PI: x);
  return x;}

float3 noise3 (float2 uvi)
{return tex2D(sampler_noise_mq,uvi)+0.5*tex2D(sampler_noise_mq,uvi*3)-.75;}

float2 otria (float2 x) {return  4*pow (frac(x)-0.5,2);}

float2 costria (float2 x) {return sat(8*abs (frac(x)-0.5)-1.5);} //entspr. dem cosinus (x*6.28)
float2 tria (float2 x) {return 2*abs(frac(x)-.5);}

float elight (float2 uvi) {return sat(.02/sqrt(length (otria(uvi/(2*M_PI))))-0.017);}

float3 RotXYZ (float3 p, float3 speed)
{ float3 c = cos (speed);
  float3 s = sin (speed);
  float3 q=p;
  q= float3 (q.x, q.y*c.x - q.z*s.x, q.y*s.x + q.z*c.x);
  q= float3 (q.x*c.y + q.z*s.y, q.y, -q.x*s.y + q.z*c.y);
  q= float3 (q.x*c.z - q.y*s.z, q.x*s.z + q.y*c.z, q.z);
  return q;}

float GetDist(float3 p)
{ float res, res1;
  p = p + float3(torus1rad,0,0);
  	float x = length(p.xz)-torus1rad;
  float umf = matan2 (p.x,p.z)*torus1rad+scenepos ;
  float wind;
  res = .5*length(float2(x, p.y));
   float y_ = p.y*compy;
   float x_ = abs(x);
  if (y_<0) //Obere Haelfte !
  {
   wind = sat(1.05-x_);
    res1 =  abs(y_)-wind*compy ;
   }
  else //Untere Haelfte
  {
    res1 = min(bridge+2*x_ - 0.5*sat(4*y_-5), abs(y_));
    if (y_>compy) {res-=1;}
  }
  return torus1dia-max(res,res1) ;
}


float GetDist2(float3 p)
{ float res, res1;
  p = p + float3(torus1rad,0,0);
  	float x = length(p.xz)-torus1rad;
  res = .5*length(float2(x, p.y));
//  res = 0.5*max(abs(x),abs(p.y)); //ist das billiger ????
  float y_ = p.y*compy;
  float x_ = abs(x);
  return torus1dia-0.5*max(x_,res) ;
}


float RayMarch(float3 ro, float3 rd) //Tunnel wall
{
    float dO=0.1;
    float dS = 1;
    while (dS > 1/quality)
    {  
       dS = GetDist(ro + rd * dO);
       dO += dS;
    }     
    return dO;}

float RayMarch2(float3 ro, float3 rd) //Refl. layer
{
    float dO=0.1;
     float dS = 1;
    while (dS > 4/quality)
    {  
       dS = GetDist2(ro + rd * dO);
       dO += dS;
    }     
    return dO;}


float3 GetNormal(float3 p)
{
   float2 e = float2(0.05,0);
   float3 n = GetDist(p).x-float3(GetDist(p-e.xyy).x, GetDist(p-e.yxy).x, GetDist(p-e.yyx).x);
   return normalize(n);
}

